/**
 * TsGenerated.mjs - whether a TypeScript file was WRITTEN BY A TOOL, for `files.generated` in BOTH TypeScript halves (plain and Angular).
 *
 * Read off the header the generator put there: a comment before the file's first token holding the `<auto-generated>` marker, as the C# half
 * reads it (`src/Map/CsRows/CsFacts.cs::Generated`), or the line generators write without the tags ("This code was generated by a tool.",
 * "... by a <name> tool."). The comments are the compiler's own scanner's (`getLeadingCommentRanges`), never a search of the text: a string
 * or a later comment saying the same words is no header. A generated file is mapped as any other - only the flag says so.
 *
 * Staged FLAT with each half's scripts, so it imports nothing by a relative folder.
 */

const MARKERS = ['<auto-generated', 'this code was generated by'];

/** 1 when a comment heading the file carries a generator's marker, else 0. */
export function generatedHeader(ts, text) {
  for (const range of ts.getLeadingCommentRanges(text, 0) ?? []) {
    const comment = text.slice(range.pos, range.end).toLowerCase();
    if (MARKERS.some((m) => comment.includes(m))) return 1;
  }
  return 0;
}
